1: function removeVaultManager(address vaultManager) external onlyGovernor {
2:         if (vaultManagerMap[vaultManager] != 1) revert NotVaultManager();
3:         delete vaultManagerMap[vaultManager];
4:         // deletion from `vaultManagerList` loop
5:         uint256 vaultManagerListLength = vaultManagerList.length;
6:         for (uint256 i = 0; i < vaultManagerListLength - 1; i++) {
7:             if (vaultManagerList[i] == vaultManager) {
8:                 // replace the `VaultManager` to remove with the last of the list
9:                 vaultManagerList[i] = vaultManagerList[vaultManagerListLength - 1];
10:                 break;
11:             }
12:         }
13:         // remove last element in array
14:         vaultManagerList.pop();

