1: function _peek(bytes6 base, bytes6 quote, uint256 amount)
2:         private view
3:         returns (uint256 value, uint256 updateTime)
4:     {
5:         Source memory source = sources[base][quote];
6:         SourceData memory sourceData;
7:         require(source.source != address(0), "Source not found");
8:         sourceData = sourcesData[source.source];
9:         if (source.inverse) {
10:             value = UniswapV3OracleLibraryMock.consult(sourceData.factory, sourceData.quoteToken, sourceData.baseToken, sourceData.fee, amount, secondsAgo);
11:         } else {
12:             value = UniswapV3OracleLibraryMock.consult(sourceData.factory, sourceData.baseToken, sourceData.quoteToken, sourceData.fee, amount, secondsAgo);
13:         }
14:         updateTime = block.timestamp - secondsAgo;

1: function _peek(bytes6 base, bytes6 quote, uint256 amountBase, uint256 updateTimeIn)
2:         private view
3:         returns (uint amountQuote, uint updateTimeOut)
4:     {
5:         IOracle source = sources[base][quote];
6:         require (address(source) != address(0), "Source not found");
7:         (amountQuote, updateTimeOut) = source.peek(base, quote, amountBase);
8:         updateTimeOut = (updateTimeOut < updateTimeIn) ? updateTimeOut : updateTimeIn;                 // Take the oldest update time
9:     }

